using System.Collections.Generic;using System.IO;using UnityEngine;using UnityEngine.Rendering;
namespace IslandGame {
 // Dense source geometry, partitioned once. Wind/contact is GPU only; no blade GameObjects.
 public sealed class SourceEnvironmentGrass:MonoBehaviour {
  public Camera view;public Transform hero;public int SourceCount,VisibleCount,DrawCalls;public bool wind=true,contact=true;
  SourceEnvironmentAssets assets;readonly Dictionary<Vector2Int,Cell> cells=new Dictionary<Vector2Int,Cell>();readonly List<Batch> pool=new List<Batch>(),batches=new List<Batch>();readonly Dictionary<int,Batch> active=new Dictionary<int,Batch>();
  sealed class Cell{public Bounds bounds;public List<Vector3> points=new List<Vector3>();}
  sealed class Batch{public int lod,count;public Matrix4x4[] matrices=new Matrix4x4[1023];public Vector4[] roots=new Vector4[1023],tips=new Vector4[1023];public float[] seeds=new float[1023];public MaterialPropertyBlock props=new MaterialPropertyBlock();}
  readonly Plane[] planes=new Plane[6];readonly Vector4[] contacts=new Vector4[4];readonly Vector3[] trail=new Vector3[3];readonly float[] trailTime={-100,-100,-100};int cursor;float next,nextTrail;Vector3 previousHero;
  static readonly int Wind=Shader.PropertyToID("_StudyWind"),Contact=Shader.PropertyToID("_StudyInteractor");
  public void Initialize(SourceEnvironmentAssets data,TextAsset positions,Camera camera,Transform target){assets=data;view=camera;hero=target;if(cells.Count>0||!positions)return;using(var r=new BinaryReader(new MemoryStream(positions.bytes))){SourceCount=r.ReadInt32();for(int i=0;i<SourceCount;i++){var p=new Vector3(r.ReadSingle(),r.ReadSingle(),r.ReadSingle());var key=new Vector2Int(Mathf.FloorToInt(p.x/4),Mathf.FloorToInt(p.z/4));if(!cells.TryGetValue(key,out var c)){c=new Cell{bounds=new Bounds(p,Vector3.one*2)};cells.Add(key,c);}c.points.Add(p);c.bounds.Encapsulate(p+Vector3.up);}}}
  void Rebuild(){batches.Clear();active.Clear();VisibleCount=0;int used=0;var center=hero?hero.position:view.transform.position;GeometryUtility.CalculateFrustumPlanes(view,planes);int level=IslandFrameBudget.Current?IslandFrameBudget.Current.Policy.Level:0;float range=level>=2?22:30;
   foreach(var cell in cells.Values){if(cell.bounds.SqrDistance(center)>range*range||!GeometryUtility.TestPlanesAABB(planes,cell.bounds))continue;foreach(var p in cell.points){float d=Vector3.Distance(center,p);if(d>range)continue;int lod=d<6?0:d<12?1:d<20?2:3;lod=Mathf.Min(3,lod+(level>=2?1:0));if(!active.TryGetValue(lod,out var b)||b.count==1023){if(used==pool.Count)pool.Add(new Batch());b=pool[used++];b.lod=lod;b.count=0;active[lod]=b;batches.Add(b);}int i=b.count++;float seed=Mathf.Repeat(p.x*13.37f+p.z*9.13f,1);b.matrices[i]=Matrix4x4.TRS(p,Quaternion.Euler(0,seed*360,0),Vector3.one*.85f);b.seeds[i]=seed;b.roots[i]=new Vector4(.075f,.16f,.025f,1);b.tips[i]=Vector4.Lerp(new Vector4(.15f,.29f,.035f,1),new Vector4(.24f,.36f,.065f,1),seed);VisibleCount++;}}
   foreach(var b in batches){b.props.SetVectorArray("_RootTint",b.roots);b.props.SetVectorArray("_TipTint",b.tips);b.props.SetFloatArray("_Seed",b.seeds);b.props.SetFloat("_StudyInteractionRadius",.75f);}DrawCalls=batches.Count;
  }
  void LateUpdate(){if(!view||!assets)return;if(Time.unscaledTime>=next){next=Time.unscaledTime+.15f;Rebuild();}if(hero&&contact){var p=hero.position;contacts[0]=new Vector4(p.x,p.y,p.z,.65f);if(Time.time>=nextTrail&&(p-previousHero).sqrMagnitude>.0025f){nextTrail=Time.time+.12f;trail[cursor]=p;trailTime[cursor]=Time.time;cursor=(cursor+1)%3;}previousHero=p;for(int i=0;i<3;i++)contacts[i+1]=new Vector4(trail[i].x,trail[i].y,trail[i].z,.65f*Mathf.Exp(-(Time.time-trailTime[i])/.65f));}else for(int i=0;i<4;i++)contacts[i]=Vector4.zero;
   foreach(var b in batches){b.props.SetVector(Wind,new Vector4(1,.35f,wind?.65f:0,Time.time*.1f));b.props.SetVectorArray(Contact,contacts);Graphics.DrawMeshInstanced(assets.grassLods[b.lod],0,assets.grassMaterial,b.matrices,b.count,b.props,ShadowCastingMode.Off,true,30,view,LightProbeUsage.Off);}}
 }
}
